package com.petlis.service.impl;
import com.fasterxml.jackson.databind.ObjectMapper;import com.petlis.common.exception.BusinessException;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.junit.jupiter.api.io.TempDir;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.context.annotation.Import;import org.springframework.transaction.annotation.Transactional;import java.nio.file.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
@SpringBootTest @Import(LegacyBankJdbcTestConfiguration.class) @Transactional("legacyBankTestTransactions") @EnabledIfEnvironmentVariable(named="PETLIS_LOCAL_DB_TEST",matches="true")
class LegacyCustomerReportLocalDatabaseTest {
 @Autowired FeatureStore store;@Autowired ObjectMapper json;@TempDir Path root;LegacyCustomerViewLocalDatabaseTest fixture;LegacyBankPaymentQuoteLocalDatabaseTest f;LegacyCustomerReportService reports;PlatformFileService files;long detail;
 @BeforeEach void setup()throws Exception{fixture=new LegacyCustomerViewLocalDatabaseTest();fixture.store=store;fixture.json=json;fixture.setup();f=fixture.f;store.jdbc().update("UPDATE lin_lb_infohospital SET PayType=0 WHERE InfoHospitalId=?",f.hospital);f.detail(f.test,"12.50",1,0);detail=fixture.detail();store.jdbc().update("UPDATE lin_lb_diagnosisdetail SET PDFHttpUrl='/Content/FilePdf/owned.pdf' WHERE DiagnosisDetailId=?",detail);Files.write(root.resolve("owned.pdf"),LegacyReportFileReaderTest.PDF);files=new PlatformFileService(store,f.access,mock(com.petlis.common.security.ReviewPermission.class),root.toString(),1024);reports=new LegacyCustomerReportService(store,fixture.service,files,new LegacyReportFileReader(root.toString(),1024));store.jdbc().update("UPDATE lin_operational_config SET config_value=JSON_SET(config_value,'$.reportDownloadEnabled',true) WHERE config_key='legacy-customer-views'");}
 LegacyCustomerViewService.Command command(){return new LegacyCustomerViewService.Command("CID",detail,null);}
 @Test void localDownloadPreservesBytesAndDoesNotRequireLegacyMailFlag()throws Exception{var before=store.one("SELECT * FROM lin_lb_diagnosisdetail WHERE DiagnosisDetailId=?",detail);assertEquals(0,((Number)before.get("IsSendMail")).intValue());var response=reports.download(command());assertArrayEquals(LegacyReportFileReaderTest.PDF,(byte[])response.getBody());assertEquals(before,store.one("SELECT * FROM lin_lb_diagnosisdetail WHERE DiagnosisDetailId=?",detail));assertTrue(response.getHeaders().getCacheControl().contains("no-store"));}
 @Test void paymentAndIndependentDownloadGateAreCheckedBeforeFileAccess(){store.jdbc().update("UPDATE lin_operational_config SET config_value=JSON_SET(config_value,'$.reportDownloadEnabled',false) WHERE config_key='legacy-customer-views'");assertEquals(409,assertThrows(BusinessException.class,()->reports.download(command())).getCode());store.jdbc().update("UPDATE lin_operational_config SET config_value=JSON_SET(config_value,'$.reportDownloadEnabled',true) WHERE config_key='legacy-customer-views'");f.detail(246,"1.00",0,0);assertEquals(409,assertThrows(BusinessException.class,()->reports.download(command())).getCode());}
 @Test void newWorkflowCannotBypassPublicationWithLegacyFileReference(){workflow("DRAFT");assertEquals(409,assertThrows(BusinessException.class,()->reports.download(command())).getCode());}
 @Test void publishedWorkflowReusesPlatformFileAndRejectsMisboundMetadata()throws Exception{long id=workflow("PUBLISHED");var saved=files.saveReport((int)f.hospital,0,id,LegacyReportFileReaderTest.PDF);store.jdbc().update("UPDATE lin_report_workflow SET pdf_file_id=? WHERE id=?",saved.id(),id);var response=reports.download(command());assertTrue(response.getBody() instanceof org.springframework.core.io.Resource);try(var input=((org.springframework.core.io.Resource)response.getBody()).getInputStream()){assertArrayEquals(LegacyReportFileReaderTest.PDF,input.readAllBytes());}store.jdbc().update("UPDATE lin_file SET biz_id='not-the-workflow' WHERE id=?",saved.id());assertEquals(409,assertThrows(BusinessException.class,()->reports.download(command())).getCode());}
 long workflow(String status){return store.insert("INSERT INTO lin_report_workflow(order_id,detail_id,test_result_id,hospital_id,laboratory_id,status) VALUES(?,?,0,?,0,?)",f.order,detail,f.hospital,status);}
}
